```python
import random

def roll_die():
    return random.randint(1, 6)

def is_even(n):
    return n % 2 == 0

def simulate_experiment(n):
    even_rolls = 0
    for _ in range(n):
        if is_even(roll_die()):
            even_rolls += 1
    return even_rolls / n

# Simulate the experiment 1,000,000 times
print(simulate_experiment(1_000_000))
```

